    'page.title' => 'All about the association',

    'section.pillar.title' => 'Three pillars of the Kolónia',
    'section.pillar.heading_1' => '1. Hungary',
    'section.pillar.content_1' => 'Our association represents Hungarians living in or visiting Berlin. It provides them with a platform to preserve their identity and connect with fellow countrymen.',
    'section.pillar.heading_2' => '2. Community',
    'section.pillar.content_2' => 'We promote cohesion and mutual support within the Hungarian community in Berlin. Through regular meetings and events, we strengthen the sense of community and offer support in various life situations.',
    'section.pillar.heading_3' => '3. Culture',
    'section.pillar.content_3' => 'The preservation and promotion of Hungarian culture is a central concern of our association. Through cultural events, readings and artistic performances, we help keep Hungarian culture alive and make it known both within the community and beyond.',
    'section.pillar.footer' => 'These three pillars form the foundation of our association and guide our actions in promoting the Hungarian community and culture in Berlin.',

    'section.numbers.title' => 'The numbers',
